<script setup>
import {computed,watch} from 'vue';import {usePage,useForm,Link} from '@inertiajs/vue3';import Layout from '../Layout.vue';
const props=defineProps({prescription:Object,events:Array});const page=usePage();const can=p=>page.props.auth.permissions.includes(p);const labels={received:'Menunggu telaah',reviewed:'Sudah ditelaah',prepared:'Sudah disiapkan',checked:'Siap di kasir'};const next=computed(()=>({received:'Simpan telaah apoteker',reviewed:'Catat penyiapan obat',prepared:'Selesaikan pemeriksaan apoteker'})[props.prescription.status]);const allowed=computed(()=>props.prescription.status==='reviewed'?can('prepare'):['received','prepared'].includes(props.prescription.status)&&can('pharmacy'));const form=useForm({id:props.prescription.id,expected_status:props.prescription.status,review:''});watch(()=>props.prescription.status,status=>{form.expected_status=status;form.review='';});
</script>
<template><Layout title="Detail pelayanan resep" module="prescriptions"><div class="page-heading"><div><Link href="/prescriptions" class="text-link">← Daftar resep</Link><h1>{{prescription.number}}</h1><p>{{labels[prescription.status]}}</p></div></div><section class="panel quick-panel"><h3>Identitas dan instruksi resep</h3><p>Pasien: {{prescription.patient_name}} · Dokter: {{prescription.doctor}} · {{prescription.date}}</p><p>Catatan: {{prescription.notes||'—'}}</p><table class="document-items"><thead><tr><th>Obat</th><th>Jumlah satuan dasar</th></tr></thead><tbody><tr v-for="item in prescription.items" :key="item.product_id"><td>{{item.name}}</td><td>{{item.quantity_base}} {{item.base_unit}}</td></tr></tbody></table></section><section v-if="allowed" class="panel quick-panel document-items"><h3>{{next}}</h3><form @submit.prevent="form.post('/actions/prescription.advance',{onSuccess:()=>form.reset('review')})"><label>Catatan tahap ini<textarea v-model="form.review" required rows="3"/></label><div v-for="error in form.errors" class="error">{{error}}</div><button class="primary" :disabled="form.processing">{{next}}</button></form></section><div v-for="error in page.props.errors" class="error">{{error}}</div><section class="panel quick-panel document-items"><h3>Riwayat tahapan dan petugas</h3><p v-for="(event,index) in events" :key="index"><strong>{{labels[event.to_status]}}</strong> · {{event.user}}<br>{{event.note}}</p><p v-if="!events.length">Resep lama belum memiliki riwayat tahapan terpisah.</p><p class="muted-note">TTK hanya mencatat penyiapan setelah telaah. Telaah dan pemeriksaan akhir tetap dilakukan apoteker. Catatan ini tidak menggantikan pemeriksaan klinis.</p></section></Layout></template>
